from pathlib import Path
p=Path("smeny_pro_mobile_build/www/index.html")
s=p.read_text(encoding="utf-8")
def rep(old,new,label):
    global s
    if old not in s: raise SystemExit("Patch target not found: "+label)
    s=s.replace(old,new,1)
rep("function openEmployee(id){let e=db.employees.find(x=>x.id===id)||{id:'',name:'',email:'',weeklyHours:40,active:true,positions:[],maxConsecutive:db.rules.maxConsecutive};","function openEmployee(id,draft){let e=draft||db.employees.find(x=>x.id===id)||{id:'',name:'',email:'',weeklyHours:40,active:true,positions:[],maxConsecutive:db.rules.maxConsecutive};","employee draft")
rep('<div class="field full"><label>Pracovní pozice / kvalifikace</label><div class="formgrid">','<div class="field full"><div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px;flex-wrap:wrap"><label style="margin:0">Pracovní pozice / kvalifikace</label><button type="button" class="ghost" onclick="openPositionFromEmployee()">＋ Přidat pozici</button></div><div class="formgrid">',"inline add button")
old="""()=>{let f=$('#empForm');if(!f.reportValidity())return;let el=n=>f.elements.namedItem(n);let x=Object.fromEntries(new FormData(f));let obj={...e,id:e.id||uid(),name:x.name.trim(),email:x.email,phone:x.phone,weeklyHours:+x.weeklyHours,maxConsecutive:+x.maxConsecutive,maxHours:+x.maxHours,positions:[...f.querySelectorAll('[name=positions]:checked')].map(i=>i.value),onlyDay:el('onlyDay').checked,onlyNight:el('onlyNight').checked,weekdays:el('weekdays').checked,isLead:el('isLead').checked,active:el('active').checked,notes:x.notes};let idx=db.employees.findIndex(a=>a.id===obj.id);if(idx>=0)db.employees[idx]=obj;else db.employees.push(obj);save();closeModal();render('employees');toast('Zaměstnanec uložen.')}"""
new="""()=>{let f=$('#empForm');if(!f.checkValidity()){f.reportValidity();return}let val=n=>f.querySelector('[name="'+n+'"]')?.value??'';let checked=n=>!!f.querySelector('[name="'+n+'"]')?.checked;let obj={...e,id:e.id||uid(),name:val('name').trim(),email:val('email'),phone:val('phone'),weeklyHours:+val('weeklyHours')||40,maxConsecutive:+val('maxConsecutive')||db.rules.maxConsecutive,maxHours:+val('maxHours')||0,positions:[...f.querySelectorAll('[name="positions"]:checked')].map(i=>i.value),onlyDay:checked('onlyDay'),onlyNight:checked('onlyNight'),weekdays:checked('weekdays'),isLead:checked('isLead'),active:checked('active'),notes:val('notes')};if(!obj.name){toast('Zadej jméno zaměstnance.');return}let idx=db.employees.findIndex(a=>a.id===obj.id),old=idx>=0?db.employees[idx]:null;if(idx>=0)db.employees[idx]=obj;else db.employees.push(obj);if(!save()){if(idx>=0)db.employees[idx]=old;else db.employees.pop();return}closeModal();render('employees');toast('Zaměstnanec uložen.')}"""
rep(old,new,"employee save")
old="""()=>{let f=$('#posForm');if(!f.reportValidity())return;let el=n=>f.elements.namedItem(n);let x={id:p.id||uid(),name:el('name').value.trim(),color:el('color').value,lead:el('lead').checked};let i=db.positions.findIndex(a=>a.id===x.id);if(i>=0)db.positions[i]=x;else db.positions.push(x);save();closeModal();render('positions');toast('Pozice uložena.')}"""
new="""()=>{let f=$('#posForm');if(!f.checkValidity()){f.reportValidity();return}let name=f.querySelector('[name="name"]').value.trim();if(!name){toast('Zadej název pozice.');return}let x={id:p.id||uid(),name,color:f.querySelector('[name="color"]').value,lead:!!f.querySelector('[name="lead"]').checked};let i=db.positions.findIndex(a=>a.id===x.id),old=i>=0?db.positions[i]:null;if(i>=0)db.positions[i]=x;else db.positions.push(x);if(!save()){if(i>=0)db.positions[i]=old;else db.positions.pop();return}closeModal();render('positions');toast('Pozice uložena.')}"""
rep(old,new,"position save")
helper="""function openPositionFromEmployee(){let f=$('#empForm');if(!f)return;let val=n=>f.querySelector('[name="'+n+'"]')?.value??'';let checked=n=>!!f.querySelector('[name="'+n+'"]')?.checked;let existing=db.employees.find(x=>x.name===val('name'));let employeeId=existing?.id||'';let draft={id:employeeId,name:val('name'),email:val('email'),phone:val('phone'),weeklyHours:+val('weeklyHours')||40,maxConsecutive:+val('maxConsecutive')||db.rules.maxConsecutive,maxHours:+val('maxHours')||0,positions:[...f.querySelectorAll('[name="positions"]:checked')].map(i=>i.value),onlyDay:checked('onlyDay'),onlyNight:checked('onlyNight'),weekdays:checked('weekdays'),isLead:checked('isLead'),active:checked('active'),notes:val('notes')};showModal('Přidat pracovní pozici','<form id="inlinePosForm" class="formgrid"><div class="field full"><label>Název pozice *</label><input name="name" required placeholder="Např. Vedoucí směny"></div><div class="field"><label>Barva</label><input name="color" type="color" value="#3267e9"></div><div class="field"><label>Typ</label><label class="checkrow"><input type="checkbox" name="lead"> Pozice vedoucího směny</label></div></form>',()=>{let pf=$('#inlinePosForm');if(!pf.checkValidity()){pf.reportValidity();return}let name=pf.querySelector('[name="name"]').value.trim();if(!name){toast('Zadej název pozice.');return}let pos={id:uid(),name,color:pf.querySelector('[name="color"]').value,lead:!!pf.querySelector('[name="lead"]').checked};db.positions.push(pos);if(!save()){db.positions.pop();return}draft.positions.push(pos.id);openEmployee(employeeId||undefined,draft);toast('Pozice přidána a vybrána. Dokonči a ulož zaměstnance.');});}
"""
rep("function deleteEmployee(id){",helper+"function deleteEmployee(id){","inline position creator")
p.write_text(s,encoding="utf-8")
print("Applied reliable employee/position forms and inline position creation.")
